{"source":"#include <stdio.h>

char temp[205];
char A[10005][204];
int top=0;

void push(char *a)
{   
   top++;
   int i;
   for(i=0;a[i]!='\0';i++)
       A[top][i]=a[i];
   A[top][i]='\0';
}

void pop()
{
    top--;
}


void pwd()
{
    int i;
    printf("/");
    for(i=1;i<=top;i++)
    {
        printf("%s/",A[i]);
    }
    printf("\n");
}

void cd(char *param)
{   
    int i,j;
    if(param[0]=='/')
    {
        top=0;
    }
    for(i=0;param[i]!='\0';i++)
    {
        if(param[i]=='/')
            continue;
        else if(param[i]=='.' && param[i+1]=='.')
        {
            i++;
            pop();
        }
        else if(param[i]=='.' && (param[i+1]=='/' || param[i+1]=='\0'))
        {
            continue;
        }
        else
        {   
            j=0;
            while(param[i]!='/' && param[i]!='\0')
            {   
                temp[j]=param[i];
                i++;
                j++;
            }
            temp[j]='\0';
            push(temp);
            if(param[i]=='\0')
                break;
        }
    }
}

int main(int argc, char *argv[])
{
    A[top][0]='/';
    A[top][1]='\0';
    int t;
    scanf("%d",&t);
    getchar();
    char input[300];
    while(t--)
    {
        scanf("%[^\n]s",input);
        getchar();


    if(input[0]=='p')
        pwd();
    else
        cd(input+3);
    }



return 0;
}"}
